import React, { useState } from 'react'; 
import { useDispatch, useSelector } from 'react-redux'; 
import './pages.css'; 
const Home = () => { const [complaint, setComplaint] = useState(''); 
    const dispatch = useDispatch(); 
    const complaints = useSelector(state => state.complaints.complaints); 
    const handleAdd = () => { 
        if(complaint.trim() !== '') { 
            dispatch({ type: 'ADD_COMPLAINT', payload: complaint }); 
    setComplaint(''); 
    } 
  }; 
    return ( <div className="page-container"> <h2>Home</h2> <div className="complaint-section"> <textarea placeholder="Enter your complaint" value={complaint} onChange={(e) => setComplaint(e.target.value)} /> 
    <button onClick={handleAdd}>Submit Complaint</button> </div> <div className="complaint-list"> 
        <h3>Complaints</h3> <ul> {complaints.map((c, i) => <li key={i}>{c}</li>)} </ul> </div> </div> ); }; 
        export default Home;
